import {describeBet,prepare} from './engine.mjs';
export function percentile(sorted,p){const t=(sorted.length-1)*p,i=Math.floor(t);return sorted[i]+(sorted[Math.ceil(t)]-sorted[i])*(t-i);}
export function summarizeRun(results){
  if(!results.length)throw Error('A completed run must contain at least one session.');
  const count=results.length,totals=Object.fromEntries(['profit','wagered','benchmark','spins','wageringSpins','limitHits'].map(k=>[k,results.reduce((sum,r)=>sum+r[k],0)]));
  const mean=totals.profit/count,sorted=results.map(r=>r.profit).sort((a,b)=>a-b),variance=count>1?results.reduce((sum,r)=>sum+(r.profit-mean)**2,0)/(count-1):0;
  const reasons={};for(const r of results)reasons[r.reason]=(reasons[r.reason]||0)+1;
  const wins=results.filter(r=>r.profit>1e-7).length,ties=results.filter(r=>Math.abs(r.profit)<=1e-7).length;
  return {count,totals,mean,sorted,variance,se:Math.sqrt(variance/count),wins,ties,losses:count-wins-ties,ruins:results.filter(r=>['bankrupt','cannot fund next bet'].includes(r.reason)).length,zero:results.filter(r=>r.bank<1e-7).length,limitSessions:results.filter(r=>r.limitHits>0).length,reasons,p10:percentile(sorted,.1),median:percentile(sorted,.5),p90:percentile(sorted,.9)};
}
const strategies={flat:'Flat: use each due rule amount.',martingale:'Martingale: double after combined net loss; reset after combined net win.',reverse:'Reverse Martingale: double after combined net win; reset after loss or configured win streak.',fibonacci:'Fibonacci: advance one step after combined net loss; move back two after combined net win.',dalembert:'D’Alembert: add one multiplier step after combined net loss; subtract one after combined net win, minimum one.'};
export function reportFilename(completedAt){const date=new Date(completedAt);return Number.isNaN(date.getTime())?'roulette-lab-report.txt':`roulette-lab-report-${date.toISOString().slice(0,19).replace(/[-:]/g,'').replace('T','-')}.txt`;}
export function createRunReport(results,c,meta={}){
  const s=summarizeRun(results),fmt=n=>new Intl.NumberFormat('en',{maximumFractionDigits:6}).format(n),pct=n=>(100*n/s.count).toFixed(2)+'%';
  const lines=['ROULETTE LAB — COMPLETED RUN REPORT','Play-money units only. Generated locally; this download sends no data to a server.','',
    'RUN AND RELEASE',`Version: ${meta.version??'Local preview / unavailable'}`,`Source commit: ${meta.commit??'Unavailable'}`,`Run started (UTC): ${meta.startedAt??'Unavailable'}`,`Run completed (UTC): ${meta.completedAt??'Unavailable'}`,`Run duration (milliseconds): ${meta.durationMs===undefined?'Unavailable':fmt(meta.durationMs)}`,`Browser: ${meta.userAgent??'Unavailable'}`,'',
    'EXPERIMENT SETTINGS',`Wheel: ${c.pockets} pockets (${c.pockets-36} zero pocket(s))`,`Seed: ${c.seed}`,`Strategy: ${strategies[c.strategy]??c.strategy}`,`Reverse reset after wins: ${c.resetWins}`,`Starting bankroll per session: ${fmt(c.bankroll)}`,`Default new-rule amount: ${fmt(c.base)}`,`Requested spins per session: ${c.spins}`,`Requested sessions: ${c.sessions}`,`Table maximum per exact placement: ${fmt(c.tableMax)}`,`At table limit: ${c.limitRule}`,`Profit stop target: ${fmt(c.takeProfit)} (0 = disabled)`,`Loss stop target: ${fmt(c.stopLoss)} (0 = disabled)`,'',
    'BETTING RULES'];
  c.bets.forEach((b,i)=>{const target=describeBet(b,c.pockets),prepared=prepare(b,c.pockets);lines.push(`Rule ${i+1}: ${target.label}`,`  Amount before progression: ${b.amount??c.base*b.units}; every ${b.every||1} spin(s); starts on spin ${b.start||1}`,`  Covered pocket IDs: ${prepared.nums.join(', ')} (37 = 00; 38 = 000)`,`  Profit payout: ${prepared.payout}:1; house edge: ${(prepared.edge*100).toFixed(6)}%`);});
  lines.push('','RUN SUMMARY',`Completed sessions: ${s.count}`,`Total requested spins: ${c.spins*c.sessions}`,`Actual spins: ${s.totals.spins}`,`Spins with bets: ${s.totals.wageringSpins}`,`Spins without bets: ${s.totals.spins-s.totals.wageringSpins}`,`Total wagered: ${fmt(s.totals.wagered)}`,`Total net profit / loss: ${fmt(s.totals.profit)}`,`Mean session profit / loss: ${fmt(s.mean)}`,`Mean house-edge cost benchmark: ${fmt(s.totals.benchmark/s.count)}`,`Monte Carlo standard error: ${s.count>1?fmt(s.se):'Not estimable from one session'}`,`Session profit minimum / maximum: ${fmt(s.sorted[0])} / ${fmt(s.sorted.at(-1))}`,`Session profit 10th percentile / median / 90th percentile: ${fmt(s.p10)} / ${fmt(s.median)} / ${fmt(s.p90)}`,`Finished ahead: ${s.wins} (${pct(s.wins)})`,`Finished break-even: ${s.ties} (${pct(s.ties)})`,`Finished behind: ${s.losses} (${pct(s.losses)})`,`Unable to fund next bet: ${s.ruins} (${pct(s.ruins)})`,`Finished with zero bankroll: ${s.zero}`,`Sessions with table-limit hits: ${s.limitSessions}`,`Total table-limit hits: ${s.totals.limitHits}`,'','SESSION STOP REASONS');
  for(const[reason,count]of Object.entries(s.reasons))lines.push(`${reason}: ${count} (${pct(count)})`);
  lines.push('','EXACT CONFIGURATION (JSON)','Use these values and seed to repeat the run. They are the settings used by the completed run, even if the UI settings later changed.',JSON.stringify(c,null,2),'','ALL SESSION RESULTS (TAB-SEPARATED)','Numeric values retain their original precision. One row per completed session.','session\tfinal_bankroll\tprofit_loss\twagered\thouse_edge_benchmark\tspins\twagering_spins\tno_bet_spins\ttable_limit_hits\tstop_reason');
  results.forEach((r,i)=>lines.push([i+1,r.bank,r.profit,r.wagered,r.benchmark,r.spins,r.wageringSpins,r.spins-r.wageringSpins,r.limitHits,r.reason].join('\t')));
  const samples=results.map((r,i)=>({r,i})).filter(({r})=>Array.isArray(r.path));
  lines.push('','SAMPLED PROFIT PATHS','The engine retains sampled paths for up to the first 12 sessions. These are not full per-spin wager logs.','session\tspin\tcumulative_profit');
  for(const{r,i}of samples)for(const point of r.path)lines.push([i+1,point.x,point.y].join('\t'));
  lines.push('','MODEL NOTES','All rules due on a spin share one progression multiplier. Combined net profit / loss changes the progression. Break-even spins and spins without bets leave it unchanged. Each session starts with a fresh bankroll and progression.','Standard profit payout: 36 / covered pockets − 1. Double-zero basket: 6:1 payout. All pockets are independent and equally likely, using seeded Mulberry32 draws.','Targets are checked between spins and can overshoot. Table limits combine duplicate exact placements. An unfundable whole stake ends the session.','House-edge cost is a benchmark computed as minus stake times house edge, not a promise of the observed result. A short run can have substantial sampling error.','Times, browser details, and download time do not affect simulation results.');
  return lines.join('\n')+'\n';
}
